"use client";

import "./switch.css";
import { Switch as BaseSwitch } from "@base-ui/react/switch";
import type React from "react";
import { cn } from "tailwind-variants";

import { SwitchContext, useSwitchContext } from "./switch.context";
import { switchVariants, type SwitchVariants } from "./switch.variants";

export type SwitchProps = SwitchVariants & React.ComponentProps<typeof BaseSwitch.Root>;

export const SwitchRoot = ({ children, className, size, ...props }: SwitchProps) => {
  const slots = switchVariants({ size });

  return (
    <SwitchContext.Provider value={{ slots }}>
      <BaseSwitch.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseSwitch.Root>
    </SwitchContext.Provider>
  );
};

export type SwitchThumbProps = React.ComponentProps<typeof BaseSwitch.Thumb>;

export const SwitchThumb = ({ className, ...props }: SwitchThumbProps) => {
  const { slots } = useSwitchContext();
  return <BaseSwitch.Thumb className={cn(slots.thumb(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const switchVariants = tv({
  slots: {
    root: "switch",
    thumb: "switch__thumb",
  },
  variants: {
    size: {
      sm: {
        root: "switch--sm",
        thumb: "switch__thumb--sm",
      },
      md: {
        root: "switch--md",
        thumb: "switch__thumb--md",
      },
      lg: {
        root: "switch--lg",
        thumb: "switch__thumb--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type SwitchVariants = VariantProps<typeof switchVariants>;

"use client";

import { createContext, useContext } from "react";

import { switchVariants } from "./switch.variants";

export type SwitchContext = {
  slots: ReturnType<typeof switchVariants>;
};

export const SwitchContext = createContext<SwitchContext | null>(null);

export const useSwitchContext = () => {
  const context = useContext(SwitchContext);
  return context ?? { slots: switchVariants() };
};

.switch {
  @apply focus-visible:outline-ring data-checked:bg-primary bg-input data-invalid:border-destructive inline-flex cursor-pointer items-center rounded-full border-2 border-transparent p-0.5 transition-colors select-none focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.switch--sm {
  @apply h-4 w-7;
}

.switch--md {
  @apply h-6 w-11;
}

.switch--lg {
  @apply h-7 w-14;
}

.switch__thumb {
  @apply bg-background pointer-events-none block rounded-full shadow-lg ring-0 transition-transform data-checked:translate-x-full data-unchecked:translate-x-0;
}

.switch__thumb--sm {
  @apply size-3 data-checked:translate-x-3;
}

.switch__thumb--md {
  @apply size-5 data-checked:translate-x-5;
}

.switch__thumb--lg {
  @apply size-6 data-checked:translate-x-7;
}

import { SwitchRoot, SwitchThumb } from "./switch";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/switch/content.md
 */
export const Switch = {
  Root: SwitchRoot,
  Thumb: SwitchThumb,
};

export { SwitchRoot, SwitchThumb };

export type { SwitchProps, SwitchThumbProps } from "./switch";
export { SwitchContext, useSwitchContext } from "./switch.context";
export { type SwitchVariants, switchVariants } from "./switch.variants";
